/// Positive keywords from measured metadata; this is not a complete value grammar.
#[must_use]
pub fn keywords(name: &str) -> Option<&'static [&'static str]> {
    KEYWORDS
        .binary_search_by_key(&name, |row| row.0)
        .ok()
        .map(|index| KEYWORDS[index].1)
}
